<template>
  <section v-if="allowed&&(checking||error||accepted)" aria-label="库存完整候选比较核对">
    <p v-if="checking">正在核对完整原件、单位、冻结任务与逐日库存和费用证明……</p>
    <el-alert v-else-if="error" type="error" :closable="false" :title="error" />
